const source = $('Validate + Prepare Audit').first().json;
let raw = $json.output ?? $json.text ?? $json;
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```\s*$/i,'').trim();

let report;
try { report = JSON.parse(raw); }
catch (e) {
  report = {
    executive_summary: 'تعذر تحويل خرج الـAgent إلى JSON منظم.',
    domain: source.domain,
    component_scores: {technical:0,cwv:0,schema:0,aeo_geo:0},
    aeo_score:0, geo_score:0, visual_seo_score:0,
    confidence:'low',
    issues:[{id:'SYS-001',type:'Technical',severity:'P1',evidence:e.message,recommended_fix:'راجع خرج الـAgent وإعداد النموذج.',human_approval:false}],
    raw_output: raw
  };
}

const clamp = v => Math.max(0, Math.min(100, Number(v ?? 0)));
const c = report.component_scores || {};
const component_scores = {
  technical: clamp(c.technical),
  cwv: clamp(c.cwv),
  schema: clamp(c.schema),
  aeo_geo: clamp(c.aeo_geo)
};
const overall_seo_score = Math.round(
  component_scores.technical * 0.30 +
  component_scores.cwv * 0.20 +
  component_scores.schema * 0.20 +
  component_scores.aeo_geo * 0.30
);

const allowed = new Set(['P0','P1','P2','P3']);
const issues = (Array.isArray(report.issues)?report.issues:[]).map((x,i)=>({
  id: x.id || `ISSUE-${String(i+1).padStart(3,'0')}`,
  type: x.type || 'Technical',
  severity: allowed.has(x.severity) ? x.severity : 'P3',
  evidence: String(x.evidence || ''),
  recommended_fix: String(x.recommended_fix || ''),
  human_approval: Boolean(x.human_approval)
}));

const lcp = Number(report?.pagespeed?.mobile?.lcp_ms);
if (Number.isFinite(lcp) && lcp > 4000 && !issues.some(x=>x.id==='CWV-001')) {
  issues.push({
    id:'CWV-001', type:'CWV', severity:'P1',
    evidence:`Mobile LCP ${lcp}ms`,
    recommended_fix:'راجع LCP element والصور الحرجة وCSS/JS وسلسلة التحميل.',
    human_approval:true
  });
}

return [{
  json:{
    success:true,
    run_id:source.run_id,
    analyzed_at:new Date().toISOString(),
    domain:source.domain,
    url:source.url,
    executive_summary:report.executive_summary || '',
    overall_seo_score,
    component_scores,
    aeo_score:clamp(report.aeo_score),
    geo_score:clamp(report.geo_score),
    visual_seo_score:clamp(report.visual_seo_score),
    confidence:report.confidence || 'medium',
    checks:report.checks || {},
    pagespeed:report.pagespeed || {},
    issues,
    recommended_actions:report.recommended_actions || {P0:[],P1:[],P2:[],P3:[]},
    methodology:'Weyaak MASTER SEO+AEO+GEO+Visual 2026 v2'
  }
}];
